export const VERTEX="#version 300 es\nprecision highp float;\nin vec3 in_pos;in vec3 in_normal;in float in_material;in vec3 in_block;in vec3 in_block_normal;\nuniform mat4 projection;uniform mat4 view;\nuniform float phase;uniform float weights[10];uniform vec3 bands;uniform float energy;\nuniform float charge;uniform float twist;uniform vec2 orbit;uniform vec2 fx;uniform float expansion;\nuniform vec4 motion;uniform vec2 motion_phase;uniform vec4 growth;uniform vec4 architecture;uniform float evolution;\nout vec3 world;out vec3 normal;out float material;out float instance;\nconst float PI=3.14159265359;\nmat3 rx(float a){float c=cos(a),s=sin(a);return mat3(1,0,0,0,c,s,0,-s,c);}\nmat3 ry(float a){float c=cos(a),s=sin(a);return mat3(c,0,-s,0,1,0,s,0,c);}\nmat3 rz(float a){float c=cos(a),s=sin(a);return mat3(c,s,0,-s,c,0,0,0,1);}\n\nvoid legacyFrame(float theta,float band,float phase,int shape,out vec3 p,out mat3 frame,out float size){\n float j=floor(theta/(PI*2.)*216.+.0001),u=j/215.,base=u*PI*2.;\n float sector=floor(j/72.),v=mod(j,72.)/71.,t=phase*.22;\n float angle=0.,roll=0.;\n if(shape==0){\n   float q=base+t*.18;\n   p=vec3(1.62*cos(q),.67*sin(q)+.15*sin(q*2.),.18*sin(q*2.));\n   vec2 tangent=vec2(-1.62*sin(q),.67*cos(q)+.3*cos(q*2.));\n   angle=atan(tangent.y,tangent.x)-PI*.5;\n   p.xy+=vec2(cos(angle),sin(angle))*(band-1.)*.085;\n   roll=.15*sin(q);size=.52+.12*sin(u*PI);\n }else if(shape==1){\n   float wave=u*PI*2.+t*.35;\n   p=vec3((u-.5)*3.85,.38*sin(wave)+(band-1.)*.12,.22*cos(wave));\n   angle=atan(.38*PI*2.*cos(wave),3.85)-PI*.5;\n   roll=.7*sin(wave*.5);size=.5;\n }else if(shape==2){\n   angle=sector*PI*2./3.+v*2.55+band*.17+t*.10;\n   float r=.35+v*1.35+band*.09;\n   p=vec3(cos(angle)*r,sin(angle)*r,.23*sin(v*PI*1.5+band*.3));\n   roll=v*2.1;size=.34+.48*sin(v*PI);\n }else if(shape==3){\n   float col=mod(j,18.),row=floor(j/18.);\n   p=vec3((col-8.5)*.20,(row-5.5)*.15,(band-1.)*.13+.16*sin(col*.35+row*.3+t*.3));\n   angle=.1*sin(t*.2);roll=0.;size=.17;\n }else if(shape==4){\n   angle=base+t*.12*(band==1.?-1.:1.);\n   float r=1.02+band*.21;\n   p=rx((band-1.)*.9)*ry(band*.27)*vec3(cos(angle)*r,sin(angle)*r,0.);\n   roll=base*.45+band*.6;size=.40;\n }else{\n   p=vec3((u-.5)*3.8,(band-1.)*.42+.20*sin(u*PI*3.+t*.4),.42*sin(u*PI*2.+t*.35+band*.6));\n   angle=-PI*.5;roll=.5*cos(u*PI*2.+t*.35);size=.55;\n }\n frame=rz(angle)*ry(roll);\n}\nvoid radialFrame(float theta,float band,float t,vec3 music,int shape,out vec3 p,out mat3 frame,out float size){\n float direction=mod(band,2.)<.5?1.:-1.;\n float a=theta+t*.105*direction+band*.085;\n float opening=.5+.5*sin(t*.43+band*.34),base=.51+band*.265;\n float harmonic=shape==6?6.:(shape==8?8.:4.);\n float strength=shape==6?.20*(.25+.75*opening):(shape==8?.19*(.4+.6*opening):.07+.08*opening);\n if(shape==9){base*=.86;strength=(.51+band*.265)*.16;}\n float radius=base+strength*cos(harmonic*a),dr=-strength*harmonic*sin(harmonic*a);\n p=vec3(cos(a)*radius,sin(a)*radius,(band-1.5)*.10+.065*cos(harmonic*a)*(.4+music.y));\n vec2 tangent=vec2(cos(a)*dr-sin(a)*radius,sin(a)*dr+cos(a)*radius);\n float angle=atan(tangent.y,tangent.x)-PI*.5;\n float hinge=(.18+.38*music.y)*sin(a*harmonic+band*.3);\n if(shape==6)hinge=.4+.45*sin(t*.43+band*.34);\n float gate=shape==6?smoothstep(.035,.22,abs(sin(a*3.))):1.;\n if(shape==8)gate=smoothstep(.025,.19,abs(sin(a*2.)));\n size=(.43+band*.012)*(.08+.92*gate);\n frame=rz(angle)*ry(hinge);\n // Facets stay discrete instead of 216 wide boxes overlapping into a gold blob.\n if(shape==9)frame=frame*mat3(1.,0.,0.,0.,.075,0.,0.,0.,.85);\n}\nvoid articulate(float theta,float band,float weights[10],inout vec3 p,inout mat3 frame){\n float kick=motion.x,body=motion.y,detail=motion.z,activity=motion.w;\n float beat=motion_phase.x,travel=motion_phase.y;\n float openForm=weights[1]+weights[5],crystal=weights[3];\n float wave=sin(theta*2.-beat*2.+band*.85);\n vec2 outward=p.xy/max(length(p.xy),.001);\n // Recoil on the attack; a travelling fold continues between the notes.\n p*=1.+kick*.20+body*.07*wave;\n p.xy+=outward*(body*.17*wave*(1.-openForm));\n p.y+=openForm*body*.32*sin(theta*2.-beat+band*.65);\n p.z+=body*(.25*sin(theta*2.-beat+band*.9)+(band-1.)*.08*sin(beat));\n p.z+=crystal*detail*.20*cos(theta*6.-beat*3.);\n float direction=mod(band,2.)<.5?1.:-1.;\n float turn=activity*.16*sin(beat*.5+band*.65)+direction*kick*.13;\n p=rz(turn)*rx(body*.16*sin(travel+band*.6))*p;\n // Hinged fins articulate as a connected mechanism rather than scattering.\n frame=rz(detail*.22*sin(theta*6.-beat*4.+band))\n       *ry(body*.65*sin(theta*2.-beat+band*.9)+kick*.42)*frame;\n}\n\nvoid evolve(float theta,float band,float weights[10],inout vec3 p,inout mat3 frame){\n float strength=evolution;\n float aperture=growth.x,curl=growth.y,spacing=growth.z,split=growth.w;\n float petals=architecture.x,elongation=architecture.y,roll=architecture.z,depth=architecture.w;\n float closed=clamp(weights[0]+weights[2]+weights[4]+weights[6]+weights[7]+weights[8]+weights[9],0.,1.);\n float angle=theta,sector=floor(theta/(PI*2.)*6.);\n float sectorAngle=(sector+.5)*PI/3.;\n float v=fract(theta/(PI*2.)*6.);\n float harmonic=mix(cos(theta*3.),cos(theta*6.),petals);\n float ripple=sin(theta*4.-motion_phase.y*1.4+band*.8);\n vec2 radial=vec2(cos(theta),sin(theta));\n // A shared hinge for each sector: connected, ordered parts rather than noise.\n vec2 pivot=vec2(cos(sectorAngle),sin(sectorAngle))*(.32+band*.045);\n float hinge=split*(.45+.40*sin(motion_phase.x*.25+band*.6))*sin((v-.5)*PI);\n mat3 fold=rz(hinge*closed);\n vec3 hinged=fold*vec3(p.xy-pivot,p.z);hinged.xy+=pivot;\n hinged.xy+=vec2(cos(sectorAngle),sin(sectorAngle))*split*.28*closed;\n p=mix(p,hinged,strength);frame=frame*(1.-strength)+(fold*frame)*strength;\n p.xy+=strength*closed*radial*(aperture*.34+harmonic*curl*.22+ripple*.035*motion.y);\n p.x*=1.+strength*(elongation-.5)*.65;\n p.y*=1.-strength*(elongation-.5)*.25;\n p.z+=strength*(band-1.)*spacing*.16;\n p.z+=strength*depth*.45*sin(theta*2.+band*.7-motion_phase.y*.6);\n float openForm=weights[1]+weights[3]+weights[5];\n float curvature=strength*openForm*(curl-.28)*1.65;\n if(abs(curvature)>.001){\n   float bend=p.x*curvature;\n   p.x=sin(bend)/curvature;p.z+=(1.-cos(bend))/curvature;\n   frame=ry(bend)*frame;\n }\n float layerRoll=strength*((roll-.5)*.55*(band-2.5)+curl*.28*sin(motion_phase.x*.125+band*.6));\n mat3 turn=rz(layerRoll+strength*.10*curl*ripple)*rx(strength*depth*.14*sin(band));\n p=turn*p;frame=turn*frame*ry(strength*(curl*.55*sin(theta*3.-motion_phase.y+band*.45)+(aperture-.5)*.6));\n}\n\nvoid structure(float theta,float band,float t,vec3 music,float weights[10],float expansion,\n               out vec3 center,out mat3 local,out float size){\n center=vec3(0.);local=mat3(0.);size=1.;\n for(int k=0;k<10;k++){\n   if(weights[k]<.00001)continue;\n   vec3 p;mat3 frame;float moduleSize;\n   if(k<6)legacyFrame(theta,band,t,k,p,frame,moduleSize);\n   else radialFrame(theta,band,t,music,k,p,frame,moduleSize);\n   center+=p*weights[k];local+=frame*ry(music.y*.20)*moduleSize*weights[k];\n }\n center*=1.+music.x*.035+expansion*(.40+band*.14);\n local*=1.+music.z*.08;\n articulate(theta,band,weights,center,local);\n evolve(theta,band,weights,center,local);\n}\n\nvoid main(){\n float id=float(gl_InstanceID),band=floor(id/216.),theta=mod(id,216.)/216.*PI*2.;\n vec3 center;mat3 local;float size;\n structure(theta,band,phase,bands,weights,expansion,center,local,size);\n float emergence=1.;\n if(band>=3.){\n   emergence=smoothstep(.04,.85,expansion)*(1.-smoothstep(band-.5,band+1.,3.+growth.z*6.));\n   center.xy*=.86+.14*emergence;center.z-=(1.-emergence)*2.8;\n }\n local=local*ry(twist*.22+charge*.13);\n float blockMix=weights[3]+weights[9];\n vec3 pos=mix(in_pos,in_block,blockMix),norm=normalize(mix(in_normal,in_block_normal,blockMix)+vec3(.000001));\n mat3 rotation=rx(orbit.y)*ry(orbit.x);\n vec3 p=rotation*(center+local*pos*size*emergence);\n world=p;normal=rotation*local*norm;material=in_material;instance=id;\n gl_Position=projection*view*vec4(p,1.);gl_Position.y+=.10*gl_Position.w;\n}\n";
export const FRAGMENT="#version 300 es\nprecision highp float;\nin vec3 world; in vec3 normal; in float material; in float instance;\nuniform float energy; uniform int palette;\nuniform vec3 camera_position;\nuniform int surface_pass;\nuniform sampler2D opaque_scene;\nuniform vec2 resolution;\nout vec4 frag;\nconst float PI=3.14159265359;\nvec3 fresnel(vec3 f0,float c){return f0+(1.-f0)*pow(1.-clamp(c,0.,1.),5.);}\nvec3 studio(vec3 r,float rough){\n float spread=rough*.35;\n // Broad studio cards with dark gaps, reflected by the actual curved normals.\n float key=exp(-pow((r.x+.36)/(.12+spread),2.)-pow((r.y-.34)/(.54+spread),4.));\n float strip=exp(-pow((r.x-.58)/(.065+spread),2.)-pow((r.y+.15)/(.72+spread),4.));\n float ceiling=pow(max(0.,r.y),12.);\n float rim=pow(max(dot(r,normalize(vec3(-.6,-.4,-.7))),0.),20.);\n return vec3(.012,.016,.024)+vec3(1.,.91,.73)*key*1.9\n       +vec3(.72,.86,1.)*strip*1.4+vec3(1.,.96,.86)*ceiling*.9\n       +vec3(.95,.61,.25)*rim*.7;\n}\nvec3 light(vec3 n,vec3 v,vec3 l,vec3 radiance,vec3 f0,float rough){\n vec3 h=normalize(v+l);\n float nl=max(dot(n,l),0.),nv=max(dot(n,v),.002),nh=max(dot(n,h),0.);\n float a=rough*rough,a2=a*a;\n float d=a2/(PI*pow(nh*nh*(a2-1.)+1.,2.)+.00001);\n float k=pow(rough+1.,2.)/8.;\n float g=nv/(nv*(1.-k)+k)*nl/(nl*(1.-k)+k);\n return fresnel(f0,max(dot(v,h),0.))*d*g/(4.*nv*max(nl,.002))*radiance*nl;\n}\nvoid main(){\n // About eight percent of whole fins are glass; the metal remains dominant.\n bool glass=mod(floor(instance)+4.,13.)<1.;\n if((surface_pass==0 && glass)||(surface_pass==1 && !glass))discard;\n vec3 n=normalize(normal);if(!gl_FrontFacing)n=-n;\n vec3 v=normalize(camera_position-world),r=reflect(-v,n);\n float nv=clamp(dot(n,v),0.,1.);\n vec3 gold=vec3(1.,.72,.30);\n if(palette==1)gold=vec3(.83,.91,.97);\n if(palette==2)gold=vec3(.96,.47,.26);\n float silver=smoothstep(.45,.65,material)*.74;\n vec3 f0=mix(gold,vec3(.91,.94,.98),silver);\n float rough=mix(.23,.16,silver);\n vec3 color=studio(r,rough)*fresnel(f0,nv);\n color+=light(n,v,normalize(vec3(-2.,3.,4.)),vec3(2.2,1.9,1.5),f0,rough);\n color+=light(n,v,normalize(vec3(3.,.7,2.)),vec3(1.,1.3,1.6),f0,rough+.07);\n color+=f0*.028*(.6+.4*max(n.y,0.));\n color*=.78+.22*abs(n.z);\n if(glass){\n   vec2 uv=gl_FragCoord.xy/resolution;\n   vec2 bend=n.xy*(.009+.012*(1.-nv));\n   vec3 behind=vec3(texture(opaque_scene,clamp(uv+bend*1.03,.001,.999)).r,\n                    texture(opaque_scene,clamp(uv+bend,.001,.999)).g,\n                    texture(opaque_scene,clamp(uv+bend*.97,.001,.999)).b);\n   float f=.045+.955*pow(1.-nv,5.);\n   vec3 tint=vec3(.87,.96,.98);\n   // Composite transmission against the resolved opaque scene, then add Fresnel.\n   color=behind*tint*(1.-f)*.96+studio(r,.07)*f;\n   color+=vec3(.15,.28,.31)*pow(1.-nv,3.)*.32;\n }\n color+=f0*energy*.025;\n frag=vec4(color,1.);\n}\n";
